-- MP-0018: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0018: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='wawasan' and type='party') then raise exception 'MP-0018: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('fathul-huzir-ayob','shamsul-anuar-nasarah','hamzah-zainudin') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0018: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('gerik','lenggong','larut') and slug not in ('fathul-huzir-ayob','shamsul-anuar-nasarah','hamzah-zainudin')) then raise exception 'MP-0018: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0018:%' and (m.source_type <> 'editorial' or e.slug not in ('fathul-huzir-ayob','shamsul-anuar-nasarah','hamzah-zainudin') or m.import_key not like 'MP-0018:' || e.slug || ':%')) then raise exception 'MP-0018: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'fathul-huzir-ayob','Fathul Huzir Ayob','opposition','Member of the Dewan Rakyat','Gerik','Perak','Fathul Huzir Ayob represents Gerik, Perak, in the Dewan Rakyat. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4093','/portraits/fathul-huzir-ayob.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P054.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4093"}, {"label": "Wawasan · announced leadership, 21 Jun 2026", "url": "https://www.thestar.com.my/news/nation/2026/06/21/parti-wawasan-negara-unveils-central-leadership-line-up"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'shamsul-anuar-nasarah','Shamsul Anuar Nasarah','government','Deputy Minister of Home Affairs','Lenggong','Perak','Shamsul Anuar Nasarah represents Lenggong, Perak, in the Dewan Rakyat. Current role: Deputy Minister of Home Affairs. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4094','/portraits/shamsul-anuar-nasarah.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P055.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4094"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'hamzah-zainudin','Hamzah Zainudin','opposition','Leader of the Opposition; President of Parti Wawasan Negara','Larut','Perak','Hamzah Zainudin represents Larut, Perak, in the Dewan Rakyat. Current role: Leader of the Opposition; President of Parti Wawasan Negara. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4095','/portraits/hamzah-zainudin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P056.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4095"}, {"label": "Wawasan · announced leadership, 21 Jun 2026", "url": "https://www.thestar.com.my/news/nation/2026/06/21/parti-wawasan-negara-unveils-central-leadership-line-up"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('fathul-huzir-ayob','shamsul-anuar-nasarah','hamzah-zainudin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0018: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0018:shamsul-anuar-nasarah:one-year-citizenship-processing','Process complete citizenship applications within a year','Governance','in_progress',null,null,'2026-07-08','https://majujohor.bernama.com/news.php?id=2578363','2026-07-08','https://majujohor.bernama.com/news.php?id=2578363','Shamsul Anuar described the Home Ministry’s one-year processing target and continuing monitoring of compliance.','Processing is not automatic approval or citizenship eligibility. A verified compliance rate and completed case denominator were not supplied; the service standard has no single calendar deadline.','2026-11-09','editorial',false from public.entities e where e.slug='shamsul-anuar-nasarah' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

